docker exec flowsbench-astropy--astropy-8707 bash -lc 'cd /testbed && python - <<'"'"'PY'"'"'
from astropy.io.fits import Card, Header
import traceback

image = b"SIMPLE  =                    T".ljust(80, b" ")
failures = []
for name, operation in (
    ("Card.fromstring", lambda: Card.fromstring(image)),
    ("Header.fromstring", lambda: Header.fromstring(image, sep="\n")),
):
    try:
        result = operation()
        if name == "Card.fromstring":
            assert result.keyword == "SIMPLE" and result.value is True
        else:
            assert result["SIMPLE"] is True
    except Exception as exc:
        print("{} failed: {}: {}".format(name, type(exc).__name__, exc))
        traceback.print_exc()
        failures.append(name)
if failures:
    raise AssertionError("Python 3 bytes rejected by: " + ", ".join(failures))
print("Header.fromstring and Card.fromstring fully parsed Python 3 bytes")
PY'

